// In Signup.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../Components/Header';
import Footer from '../Components/Footer';
import '../CSS/login.css';

function Signup() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const navigate = useNavigate();

  // Remove this function declaration
  // const handleSubmit = (event) => {
  //   event.preventDefault();
  //   // Handle sign up logic here
  //   navigate('/'); // Navigate to the home page after successful sign up
  // };

  // Keep only this function declaration
  const handleSubmit = async (event) => {
    event.preventDefault();

    // Send a POST request to the /signup route on your Express server
    const response = await fetch('/signup', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        username,
        email,
        password,
      }),
    });

    // Handle the response from the server
    if (response.ok) {
      // Signup was successful
      // TODO: Redirect the user to another page or show a success message
    } else {
      // Signup failed
      // TODO: Show an error message to the user
    }
  };

  return (
    <>
      <Header />
      <div className="signup-container">
        <div className="signup-form">
          <h1>Sign Up</h1>
          <form onSubmit={handleSubmit}>
            <label htmlFor="email">Email:</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
            />
            <br />
            <label htmlFor="password">Password:</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
            />
            <br />
            <label htmlFor="username">Username:</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(event) => setUsername(event.target.value)}
            />
            <br />
            <button type="submit">Sign Up</button>
          </form>
        </div>
        <div className="signup-image">
          <img src="./images/cover.jpg" alt="cover" />
        </div>
      </div>
      <Footer />
    </>
  );
}

export default Signup;

